//! Swift bindings for `asiri-core` (architecture §6.3), generated by UniFFI.
//!
//! The app holds one [`AsiriCore`]. Synchronous calls touch only the encrypted database and
//! return quickly; `async` calls (pairing, group changes, calls, files) run on the core's own
//! runtime and are awaited from Swift. Everything the app shows arrives as a [`CoreEvent`] on the
//! [`CoreListener`] it registers.
//!
//! IDs cross the boundary as raw bytes (`Data` in Swift): 16 bytes for users, messages, devices
//! and calls; 32 for chats.

use std::future::Future;
use std::path::PathBuf;
use std::sync::Arc;

use asiri_core::crypto::sas::EmojiWord;
use asiri_core::engine::{self, AttachmentInput, ChatFlag as CoreChatFlag};
use asiri_core::ids::{Id16, id16};
use asiri_core::store;
use asiri_core::{Core, CoreConfig, CoreError};

uniffi::setup_scaffolding!();

// ─── errors ─────────────────────────────────────────────────────────────────

/// Why a call failed. `message` is plain language, safe to show.
#[derive(Debug, thiserror::Error, uniffi::Error)]
pub enum AsiriError {
    /// Not connected to the server right now.
    #[error("You're offline")]
    Offline,
    /// The server refused the request.
    #[error("{message}")]
    Relay { message: String },
    /// A pairing code was wrong, expired or already used.
    #[error("{message}")]
    Pairing { message: String },
    /// The input was not acceptable.
    #[error("{message}")]
    Invalid { message: String },
    /// The thing asked for doesn't exist.
    #[error("Not found")]
    NotFound,
    /// This Mac isn't paired with a server yet.
    #[error("This Mac isn't connected to a server yet")]
    NotRegistered,
    /// The admin rules don't allow it.
    #[error("{message}")]
    NotAllowed { message: String },
    /// Something cryptographic failed (a tampered message, a key mismatch).
    #[error("{message}")]
    Crypto { message: String },
    /// The encrypted database failed.
    #[error("{message}")]
    Storage { message: String },
    /// A network problem.
    #[error("{message}")]
    Network { message: String },
    /// A bug.
    #[error("{message}")]
    Internal { message: String },
}

impl From<CoreError> for AsiriError {
    fn from(e: CoreError) -> Self {
        let message = e.to_string();
        match e {
            CoreError::Offline => Self::Offline,
            CoreError::Relay(m) => Self::Relay { message: m },
            CoreError::Pairing(m) => Self::Pairing { message: m },
            CoreError::Invalid(m) => Self::Invalid { message: m },
            CoreError::NotFound => Self::NotFound,
            CoreError::NotRegistered => Self::NotRegistered,
            CoreError::NotAllowed(m) => Self::NotAllowed { message: m },
            CoreError::Crypto(m) => Self::Crypto { message: m },
            CoreError::Storage(m) => Self::Storage { message: m },
            CoreError::Network(m) => Self::Network { message: m },
            CoreError::Io(_) => Self::Storage { message },
            CoreError::Internal(m) => Self::Internal { message: m },
        }
    }
}

type Result<T> = std::result::Result<T, AsiriError>;

fn id(bytes: &[u8]) -> Result<Id16> {
    id16(bytes).ok_or_else(|| AsiriError::Invalid {
        message: "malformed ID".into(),
    })
}

fn ids(list: &[Vec<u8>]) -> Result<Vec<Id16>> {
    list.iter().map(|b| id(b)).collect()
}

