/// One emoji of a verification sequence.
#[derive(Clone, Debug, PartialEq, Eq, uniffi::Record)]
pub struct Emoji {
    /// The glyph.
    pub glyph: String,
    /// Its name, read aloud when comparing.
    pub name: String,
}

impl From<EmojiWord> for Emoji {
    fn from(e: EmojiWord) -> Self {
        Self {
            glyph: e.emoji,
            name: e.name,
        }
    }
}

fn emoji(list: Vec<EmojiWord>) -> Vec<Emoji> {
    list.into_iter().map(Into::into).collect()
}

