impl From<store::AttachmentInfo> for Attachment {
    fn from(a: store::AttachmentInfo) -> Self {
        Self {
            size: a.size,
            mime: a.mime,
            file_name: a.file_name,
            width: a.width,
            height: a.height,
            duration_ms: a.duration_ms,
            thumbnail: a.thumbnail,
            blurhash: a.blurhash,
            voice_note: a.voice_note,
            waveform: a.waveform,
            state: a.state.map_or(AttachmentState::Remote, Into::into),
            progress: a.progress,
        }
    }
}

/// A message.
#[derive(Clone, Debug, PartialEq, uniffi::Record)]
pub struct CoreMessage {
    /// Message ID (16 bytes).
    pub message_id: Vec<u8>,
    /// Chat ID.
    pub chat_id: Vec<u8>,
    /// Author.
    pub sender: Vec<u8>,
    /// Sent by the user.
    pub outgoing: bool,
    /// Kind.
    pub kind: MessageKind,
    /// Text, caption or system line.
    pub body: String,
    /// The message this replies to.
    pub reply_to: Option<Vec<u8>>,
    /// Sender's clock (Unix ms).
    pub sent_at_ms: i64,
    /// Arrival on this Mac.
    pub received_at_ms: i64,
    /// Ordering key.
    pub sort_ms: i64,
    /// Delivery state.
    pub status: MessageStatus,
    /// Edited.
    pub edited: bool,
    /// Deleted for everyone.
    pub deleted: bool,
    /// Disappears at (Unix ms).
    pub expires_at_ms: Option<i64>,
    /// For attachments.
    pub attachment: Option<Attachment>,
    /// Reactions.
    pub reactions: Vec<Reaction>,
}

impl From<store::Message> for CoreMessage {
    fn from(m: store::Message) -> Self {
        Self {
            message_id: m.message_id.to_vec(),
            chat_id: m.chat_id,
            sender: m.sender_user.to_vec(),
            outgoing: m.outgoing,
            kind: m.kind.into(),
            body: m.body,
            reply_to: m.reply_to.map(|r| r.to_vec()),
            sent_at_ms: m.sent_at_ms,
            received_at_ms: m.received_at_ms,
            sort_ms: m.sort_ms,
            status: m.status.into(),
            edited: m.edited,
            deleted: m.deleted,
            expires_at_ms: m.expires_at_ms,
            attachment: m.attachment.map(Into::into),
            reactions: m
                .reactions
                .into_iter()
                .map(|r| Reaction {
                    emoji: r.emoji,
                    count: r.count,
                    mine: r.mine,
                })
                .collect(),
        }
    }
}

/// A chat as the chat list shows it.
#[derive(Clone, Debug, PartialEq, uniffi::Record)]
pub struct CoreChat {
    /// Chat ID (32 bytes).
    pub chat_id: Vec<u8>,
    /// Direct or group.
    pub kind: ChatKind,
    /// Group name or the other person's name.
    pub title: String,
    /// Group description.
    pub description: String,
    /// Group photo or the other person's photo (JPEG).
    pub avatar: Option<Vec<u8>>,
    /// For DMs: the other person.
    pub peer: Option<Vec<u8>>,
    /// The newest message.
    pub last_message: Option<CoreMessage>,
    /// Who sent it (groups).
    pub last_sender_name: Option<String>,
    /// For DMs: the other person's verification.
    pub verification: Option<Verification>,
    /// Members, including the user.
    pub member_count: u32,
    /// The user is an admin.
    pub is_admin: bool,
    /// Unread messages.
    pub unread: u32,
    /// No notifications.
    pub muted: bool,
    /// Pinned.
    pub pinned: bool,
    /// Archived.
    pub archived: bool,
    /// Disappearing-message timer in seconds (0 = off).
    pub timer_seconds: u32,
    /// The user is no longer a member.
    pub left: bool,
    /// Newest activity (Unix ms).
    pub last_activity_ms: i64,
}

impl From<engine::ChatSummary> for CoreChat {
    fn from(c: engine::ChatSummary) -> Self {
        Self {
            chat_id: c.chat.chat_id,
            kind: c.chat.kind.into(),
            title: c.title,
            description: c.chat.description,
            avatar: c.avatar,
            peer: c.chat.dm_user.map(|u| u.to_vec()),
            last_message: c.last_message.map(Into::into),
            last_sender_name: c.last_sender_name,
            verification: c.verification.map(Into::into),
            member_count: c.member_count,
            is_admin: c.is_admin,
            unread: c.chat.unread,
            muted: c.chat.muted,
            pinned: c.chat.pinned,
            archived: c.chat.archived,
            timer_seconds: c.chat.timer_s,
            left: c.chat.left,
            last_activity_ms: c.chat.last_activity_ms,
        }
    }
}

